import{observe}from"../observe.js";let interactionCountEstimate=0,minKnownInteractionId=1/0,maxKnownInteractionId=0;const updateEstimate=n=>{for(const t of n)t.interactionId&&(minKnownInteractionId=Math.min(minKnownInteractionId,t.interactionId),maxKnownInteractionId=Math.max(maxKnownInteractionId,t.interactionId),interactionCountEstimate=maxKnownInteractionId?(maxKnownInteractionId-minKnownInteractionId)/7+1:0)};let po;export const getInteractionCount=()=>po?interactionCountEstimate:performance.interactionCount??0;export const initInteractionCountPolyfill=()=>{"interactionCount"in performance||po||(po=observe("event",updateEstimate,{durationThreshold:0}))};